window.ACTIVIDAD = {"id": "ut2-06-que-estructura-es", "titulo": "¿Qué estructura es?", "subtitulo": "UT2 · Diseño y desarrollo web · 3º EAS Diseño Gráfico", "etiqueta": "UT2 · Diseño y desarrollo web", "objetivo": "Reconocer en un mapa del sitio si la estructura es jerárquica, hipertexto, lineal o de red, y saber qué ventaja e inconveniente tiene cada una.", "minutos": 20, "preguntasPorIntento": 10, "aprobado": 50, "garantizar": ["arrastrar", "emparejar"], "instrucciones": {"arrastrar": "Arrastra cada tipo de estructura a su esquema. También puedes pulsar un tipo y después su zona. Sobra un término. Cada zona bien rellenada suma.", "emparejar": "Arrastra cada frase junto a su estructura. También puedes pulsar una frase y después su hueco. Sobra una frase. Cada pareja bien hecha suma."}, "diapositivas": {"84": "La arquitectura de la información tiene 3 focos principales: organización, etiquetado y estructura.", "90": "Organización. Tipos más comunes: cronológica, alfabética y temática.", "94": "Etiquetado. Qué hacemos: definir la terminología que utilizará el sistema. Cómo: eligiendo las palabras para títulos, encabezados, nombres de secciones, palabras clave, productos y transacciones. La buena voluntad no basta: hay que hacer un test UX a los usuarios para conocer cómo lo llamarían, cómo lo buscarían y si entienden la terminología.", "101": "Estructura. Qué hacemos: definir el modelo de navegación y las herramientas de búsqueda. Si no lo hacemos bien, los usuarios ignorarán la navegación, porque no les parece natural, previsible y familiar. Hay que considerar las experiencias previas y los patrones más repetidos. Es un compendio de agrupación, profundidad y etiquetado de los contenidos.", "102": "Estructura jerárquica: navegación en forma de árbol. Se organiza de lo general a lo concreto. Es de las más populares. Esquema: un bloque arriba del que bajan tres, y de cada uno baja otro.", "103": "Jerárquica. Ventaja: el usuario puede hacerse un mapa mental del sitio y saber dónde está, qué categoría está viendo y cómo ha llegado. Inconveniente: para ir a otro sitio debe volver sobre sus pasos o comenzar de nuevo; no se permite la libre navegación.", "104": "Hipertexto: la información no se organiza de forma lineal; los bloques están conectados por cualquier tipo de asociación. Esquema: bloques unidos con flechas de izquierda a derecha cuyos caminos se abren y se vuelven a juntar.", "105": "Hipertexto. Ventaja: más libre y flexible; las asociaciones y relaciones de contenido enriquecen la experiencia del usuario. Inconveniente: es difícil para los usuarios entender el sistema, memorizar un recorrido o encontrar lo que buscan de forma directa.", "106": "Navegación plana o lineal: desde un bloque de información se puede pasar solo al siguiente o solo al anterior. Esquema: tres bloques en fila unidos con flechas de ida y vuelta, cada uno con otro bloque debajo.", "107": "Lineal. Ventaja: útil si queremos que el usuario siga un itinerario fijo y guiado, evitando que otros bloques le distraigan. Inconveniente: solo es posible cuando el volumen de información o su tipología es simple o las opciones del usuario son reducidas.", "108": "Navegación de red: desde el origen se accede a otros bloques sin orden aparente. Hay lógica, pero no hay orden (primero, segundo…). Esquema: mapa conceptual con muchos conceptos unidos por relaciones.", "109": "Red. Ventaja: es una estructura más libre que permite organizar información relacionada pero de tipologías dispares. Inconveniente: no es recomendable para cantidades de información muy grandes; el usuario se desorientará y no sabrá dónde se encuentra."}, "banco": [{"id": "q01", "tipo": "unica", "enunciado": "Este es el mapa del sitio de la tienda online Pasos Ligeros. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-tienda.svg", "alt": "Mapa del sitio. De Inicio salen tres secciones: Mujer, Hombre y Niños. De Mujer salen Zapatillas y Botas; de Hombre, Zapatillas y Sandalias; de Niños, Colegio y Deporte. No hay más enlaces.", "opciones": [{"id": "j", "texto": "Jerárquica", "correcta": true}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red"}], "explicacion": "Es jerárquica: un árbol que va de lo general (Inicio) a lo concreto (Botas). Cada página cuelga de una sola sección. No es lineal, porque desde Inicio eliges entre tres caminos. Tampoco es hipertexto ni red, porque ningún enlace cruza de una rama a otra.", "diapositiva": 102}, {"id": "q02", "tipo": "unica", "enunciado": "El Ayuntamiento de Villaverde del Río ha dibujado su web como las carpetas de un ordenador. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-ayuntamiento.svg", "alt": "Lista con sangrías. Inicio contiene Trámites, Agenda y Ciudad. Trámites contiene Empadronamiento y Licencias. Licencias contiene Obras y Terrazas. Agenda contiene Conciertos y Mercadillos. Ciudad contiene Parques.", "opciones": [{"id": "j", "texto": "Jerárquica", "correcta": true}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red"}], "explicacion": "Es jerárquica, aunque no esté dibujada como un árbol vertical. Cada página está dentro de una sola sección y se baja de lo general a lo concreto en cuatro niveles. Las carpetas de un ordenador son un árbol. Su inconveniente: para ir de Terrazas a Conciertos hay que subir y volver a bajar.", "diapositiva": 102}, {"id": "q03", "tipo": "unica", "enunciado": "Este es el mapa del curso online «Acuarela desde cero». ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-curso.svg", "alt": "Cinco bloques en fila: Bienvenida, Tema 1, Tema 2, Tema 3 y Diploma. Cada bloque enlaza en los dos sentidos solo con el de al lado. Debajo de cada tema hay un bloque Ejercicios.", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal", "correcta": true}, {"id": "r", "texto": "De red"}], "explicacion": "Es plana o lineal: desde cada bloque solo se pasa al siguiente o al anterior. Es igual que el esquema de la diapositiva 106, que también tiene un bloque debajo de cada paso. Los ejercicios no abren caminos nuevos: el itinerario sigue siendo uno.", "diapositiva": 106}, {"id": "q04", "tipo": "unica", "enunciado": "Así es la reserva de entradas en la web del Cine Lumière. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-reserva.svg", "alt": "Seis pantallas dibujadas en dos filas, en zigzag: Película, Sesión, Butacas, Tus datos, Pago y Entrada en el móvil. Cada pantalla enlaza en los dos sentidos solo con la anterior y con la siguiente.", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal", "correcta": true}, {"id": "r", "texto": "De red"}], "explicacion": "Es lineal aunque esté dibujada en dos filas: el zigzag es solo para que quepa. Cada pantalla lleva únicamente a la anterior o a la siguiente. Esa es su ventaja: un itinerario fijo y guiado, sin distracciones, para terminar la compra.", "diapositiva": 106}, {"id": "q05", "tipo": "unica", "enunciado": "Así se enlazan las páginas de la wiki de cine Cinéfilos. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-wiki.svg", "alt": "Ocho páginas unidas con flechas de izquierda a derecha. Película lleva a Directora y a Reparto. Directora lleva a Otras películas. Reparto lleva a Actriz, y Actriz también lleva a Otras películas. Otras películas y Actriz llevan a Premios. Premios lleva a Festival y a Ciudad, y Ciudad también lleva a Festival.", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto", "correcta": true}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red"}], "explicacion": "Es hipertexto: los bloques se conectan por asociaciones (una actriz con otras películas, unos premios con un festival). Los caminos se abren y se vuelven a juntar, como en la diapositiva 104. No es jerárquica, porque a Premios se llega desde dos páginas. No es de red, porque no hay un origen central rodeado de bloques, sino un recorrido que avanza.", "diapositiva": 104}, {"id": "q06", "tipo": "unica", "enunciado": "Así se enlazan las entradas del blog de recetas La Despensa. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-recetas.svg", "alt": "Ocho entradas unidas con flechas de arriba abajo. Gazpacho lleva a Tomate y a Aceite de oliva. Tomate lleva a Salmorejo, y Salmorejo también lleva a Aceite de oliva. Aceite de oliva lleva a Almazaras de Jaén. Salmorejo y Almazaras de Jaén llevan a Pan de pueblo. Pan de pueblo lleva a Hornos y a Tostadas, y Tostadas también lleva a Hornos.", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto", "correcta": true}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red"}], "explicacion": "Es hipertexto: cada entrada enlaza con otras por asociación (una receta con su ingrediente, un ingrediente con otra receta). Los caminos se abren y se cruzan. No es jerárquica, porque una entrada tiene varias de origen. Su inconveniente: cuesta memorizar el recorrido o llegar directo a algo.", "diapositiva": 104}, {"id": "q07", "tipo": "unica", "enunciado": "Así se relacionan las secciones de la web del Festival Sonora. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-festival.svg", "alt": "Festival está en el centro, unido con líneas sin flecha a Artistas, Escenarios, Entradas, Transporte y Alojamiento. Las secciones de alrededor también se unen entre sí: Artistas con Escenarios, Escenarios con Horarios, Horarios con Entradas, Entradas con Comida, Transporte con Alojamiento y Alojamiento con Artistas. Algunas líneas llevan una palabra que explica la relación.", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red", "correcta": true}], "explicacion": "Es de red: desde el origen (Festival) se llega a bloques muy distintos (artistas, comida, transporte) sin un orden. Cada relación tiene lógica, pero no hay un primero ni un segundo, como en el mapa de la diapositiva 108. No es jerárquica, porque las secciones se cruzan entre sí. No es hipertexto, porque no hay un recorrido que avance: todo gira alrededor del origen.", "diapositiva": 108}, {"id": "q08", "tipo": "unica", "enunciado": "Así se relacionan las secciones de la web del Museo del Barro. ¿Qué tipo de estructura tiene?", "instruccion": "Mira el mapa y elige su tipo de estructura.", "imagen": "img/mapa-museo.svg", "alt": "Exposición está en el centro, unida con líneas sin flecha a Piezas, Materiales, Talleres y Épocas. Las secciones de alrededor también se unen entre sí: Piezas con Técnicas y con Autoras, Técnicas con Materiales, Materiales con Épocas, Épocas con Autoras y con Talleres, y Autoras con Talleres. Algunas líneas llevan una palabra que explica la relación.", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red", "correcta": true}], "explicacion": "Es de red: desde el origen (Exposición) se accede a bloques de tipos muy distintos (piezas, autoras, talleres) sin orden aparente. Hay lógica en cada relación, pero no hay orden. Con pocas secciones funciona; con muchísimas, el usuario se desorientaría.", "diapositiva": 108}, {"id": "q09", "tipo": "arrastrar", "grupo": "cuatro", "enunciado": "Estos cuatro esquemas no tienen texto. ¿Qué tipo de estructura es cada uno?", "imagen": "img/cuatro-estructuras-a.svg", "alt": "Cuatro esquemas sin texto. Zona 1: un bloque arriba del que bajan tres; del primero de esos tres bajan otros dos. Zona 2: bloques unidos con flechas de izquierda a derecha; el camino se abre en dos y se vuelve a juntar, dos veces. Zona 3: cuatro bloques en fila, cada uno unido al de al lado con flechas de ida y vuelta. Zona 4: un bloque central unido a cinco bloques que lo rodean, que también se unen entre sí con líneas sin flecha.", "zonas": [{"id": "z1", "x": 25.4, "y": 6.7, "correcta": "t1"}, {"id": "z2", "x": 74.6, "y": 6.7, "correcta": "t2"}, {"id": "z3", "x": 25.4, "y": 55.8, "correcta": "t3"}, {"id": "z4", "x": 74.6, "y": 55.8, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Jerárquica"}, {"id": "t2", "texto": "Hipertexto"}, {"id": "t3", "texto": "Plana o lineal"}, {"id": "t4", "texto": "De red"}, {"id": "t5", "texto": "Alfabética"}], "explicacion": "1 es jerárquica: un árbol de lo general a lo concreto. 2 es hipertexto: bloques asociados cuyos caminos se abren y se juntan. 3 es lineal: solo se pasa al siguiente o al anterior. 4 es de red: desde un origen se llega a bloques sin orden. «Alfabética» sobra: es un tipo de organización (cómo agrupamos el contenido), no de estructura.", "diapositiva": 102}, {"id": "q10", "tipo": "arrastrar", "grupo": "cuatro", "enunciado": "Estos cuatro esquemas están dibujados sin texto. ¿Qué estructura representa cada uno?", "imagen": "img/cuatro-estructuras-b.svg", "alt": "Cuatro esquemas sin texto. Zona 1: un bloque central unido a seis bloques que lo rodean, que también se unen entre sí con líneas sin flecha. Zona 2: cuatro bloques en columna, cada uno unido al de abajo con flechas de ida y vuelta. Zona 3: un bloque arriba del que bajan tres; del primero baja uno y del tercero bajan dos. Zona 4: dos bloques que confluyen en uno; de ahí el camino se abre en dos, se cruza y termina en otros dos bloques.", "zonas": [{"id": "z1", "x": 25.4, "y": 6.7, "correcta": "t4"}, {"id": "z2", "x": 74.6, "y": 6.7, "correcta": "t3"}, {"id": "z3", "x": 25.4, "y": 55.8, "correcta": "t1"}, {"id": "z4", "x": 74.6, "y": 55.8, "correcta": "t2"}], "terminos": [{"id": "t1", "texto": "Jerárquica"}, {"id": "t2", "texto": "Hipertexto"}, {"id": "t3", "texto": "Plana o lineal"}, {"id": "t4", "texto": "De red"}, {"id": "t5", "texto": "Alfabética"}], "explicacion": "1 es de red: un origen rodeado de bloques unidos sin orden. 2 es lineal aunque vaya en vertical: solo se pasa al anterior o al siguiente. 3 es jerárquica: un árbol, aunque las ramas no tengan el mismo número de hijos. 4 es hipertexto: los bloques se asocian y los caminos se juntan y se separan. «Alfabética» sobra: es un tipo de organización, no de estructura.", "diapositiva": 108}, {"id": "q11", "tipo": "emparejar", "enunciado": "Cada estructura tiene su ventaja. Empareja cada una con la suya.", "pares": [{"id": "p1", "izquierda": "Jerárquica", "derecha": "El usuario se hace un mapa mental del sitio: sabe dónde está y cómo ha llegado."}, {"id": "p2", "izquierda": "Hipertexto", "derecha": "Las asociaciones entre contenidos enriquecen la experiencia. Es libre y flexible."}, {"id": "p3", "izquierda": "Plana o lineal", "derecha": "El usuario sigue un itinerario fijo y guiado, sin bloques que le distraigan."}, {"id": "p4", "izquierda": "De red", "derecha": "Permite organizar información relacionada pero de tipos muy distintos."}], "distractores": ["Evita tener que investigar con usuarios antes de diseñar el menú."], "explicacion": "Jerárquica: orienta, porque el usuario sabe dónde está. Hipertexto: las asociaciones enriquecen la experiencia. Lineal: guía sin distracciones. Red: reúne información relacionada de tipos dispares. Ninguna estructura evita investigar con usuarios: la arquitectura de la información se basa en su modelo mental. Repasa también las diapositivas 105, 107 y 109.", "diapositiva": 103}, {"id": "q12", "tipo": "emparejar", "grupo": "jerarquica-libre", "enunciado": "Cada estructura tiene su inconveniente. Empareja cada una con el suyo.", "pares": [{"id": "p1", "izquierda": "Jerárquica", "derecha": "Para ir a otra rama hay que volver atrás o empezar de nuevo. No hay libre navegación."}, {"id": "p2", "izquierda": "Hipertexto", "derecha": "Cuesta entender el sistema, memorizar un recorrido o llegar directo a algo."}, {"id": "p3", "izquierda": "Plana o lineal", "derecha": "Solo sirve si hay poca información, es sencilla o hay pocas opciones."}, {"id": "p4", "izquierda": "De red", "derecha": "No conviene con muchísima información: el usuario se desorienta."}], "distractores": ["Las páginas tardan más en cargar en el navegador."], "explicacion": "Jerárquica: obliga a volver sobre tus pasos. Hipertexto: es difícil de entender y de recorrer de forma directa. Lineal: solo vale con poca información o pocas opciones. Red: con muchísima información desorienta. La velocidad de carga no depende del tipo de estructura: es un asunto técnico. Repasa también las diapositivas 103, 105 y 107.", "diapositiva": 109}, {"id": "q13", "tipo": "clasificar", "enunciado": "En un test con usuarios, varias personas comentan webs distintas. ¿De qué estructura habla cada comentario?", "instruccion": "Elige una estructura para cada comentario. Cada comentario bien clasificado suma.", "categorias": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red"}], "elementos": [{"id": "e1", "texto": "«Siempre sé en qué sección estoy, pero para pasar de Ropa a Libros tengo que volver al inicio».", "categoria": "j"}, {"id": "e2", "texto": "«El menú va de lo general a lo concreto: Deportes, luego Fútbol, luego Botas».", "categoria": "j"}, {"id": "e3", "texto": "«Saltando de un enlace a otro aprendí cosas que no buscaba, pero no sabría repetir el camino».", "categoria": "h"}, {"id": "e4", "texto": "«Para encontrar algo concreto voy de asociación en asociación; no hay un camino directo».", "categoria": "h"}, {"id": "e5", "texto": "«El formulario solo me deja ir al paso siguiente o al anterior, y así no me distraigo».", "categoria": "l"}, {"id": "e6", "texto": "«Con cuatro pantallas va bien, pero elegir así entre doscientos productos sería eterno».", "categoria": "l"}, {"id": "e7", "texto": "«Desde la portada llego a cosas muy distintas, como horarios, comida o artistas, sin ningún orden».", "categoria": "r"}, {"id": "e8", "texto": "«Tenía tantísimas secciones unidas entre sí sin orden que acabé sin saber dónde estaba».", "categoria": "r"}], "explicacion": "Saber dónde estás pero tener que volver atrás, o bajar de lo general a lo concreto, es jerárquica. Enriquecerse con asociaciones pero no poder memorizar el recorrido ni llegar directo es hipertexto. Ir solo al siguiente o al anterior, y que no sirva para mucha información, es lineal. Llegar desde el origen a cosas dispares sin orden, y perderse cuando hay muchísimo, es de red.", "diapositiva": 105}, {"id": "q14", "tipo": "clasificar", "enunciado": "La organización agrupa los contenidos. ¿Qué tipo de organización usa cada ejemplo?", "instruccion": "Elige un tipo de organización para cada ejemplo. Cada ejemplo bien clasificado suma.", "categorias": [{"id": "c", "texto": "Cronológica"}, {"id": "a", "texto": "Alfabética"}, {"id": "t", "texto": "Temática"}], "elementos": [{"id": "e1", "texto": "Las noticias de un blog, de la más reciente a la más antigua.", "categoria": "c"}, {"id": "e2", "texto": "La agenda de conciertos de un teatro, ordenada por fecha.", "categoria": "c"}, {"id": "e3", "texto": "Un glosario de términos de diseño, de la A a la Z.", "categoria": "a"}, {"id": "e4", "texto": "El directorio del profesorado, ordenado por apellido.", "categoria": "a"}, {"id": "e5", "texto": "Una tienda con las secciones Ropa, Calzado y Accesorios.", "categoria": "t"}, {"id": "e6", "texto": "Un recetario con Entrantes, Principales y Postres.", "categoria": "t"}], "explicacion": "Los tipos más comunes de organización son cronológica (por fecha), alfabética (por orden de letras) y temática (por tema). Organizar es categorizar: crear grupos de contenidos relacionados para que el usuario encuentre lo que busca sin sobrecarga cognitiva.", "diapositiva": 90}, {"id": "q15", "tipo": "unica", "enunciado": "La ONG Manos Verdes quiere que su proceso de donación se complete sin que nada distraiga. ¿Qué estructura le conviene para ese proceso?", "opciones": [{"id": "j", "texto": "Jerárquica"}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal", "correcta": true}, {"id": "r", "texto": "De red"}], "explicacion": "La lineal es útil cuando queremos que el usuario siga un itinerario fijo y guiado, sin que otros bloques le distraigan. Una donación tiene pocos pasos y pocas opciones, así que su inconveniente no pesa. La jerárquica, el hipertexto y la red dejan elegir caminos, y eso aquí distrae.", "diapositiva": 107}, {"id": "q16", "tipo": "unica", "enunciado": "Lucía quiere que en la web de su estudio el usuario sepa siempre en qué sección está y cómo ha llegado. ¿Qué estructura le conviene?", "opciones": [{"id": "j", "texto": "Jerárquica", "correcta": true}, {"id": "h", "texto": "Hipertexto"}, {"id": "l", "texto": "Plana o lineal"}, {"id": "r", "texto": "De red"}], "explicacion": "La ventaja de la jerárquica es que el usuario se hace un mapa mental del sitio: sabe dónde está, qué categoría ve y cómo ha llegado. El hipertexto y la red son más libres, pero cuesta saber dónde estás. La lineal guía bien, pero solo sirve para recorridos cortos y sencillos.", "diapositiva": 103}, {"id": "q17", "tipo": "unica", "enunciado": "Una tienda online duda entre llamar a una sección «Devoluciones» o «Cambios y reembolsos». Según el temario, ¿cómo debería decidirlo?", "opciones": [{"id": "a", "texto": "Con un test UX: cómo la llamarían y cómo la buscarían sus usuarios.", "correcta": true}, {"id": "b", "texto": "Copiando la etiqueta que usa la tienda más grande del sector."}, {"id": "c", "texto": "Con la palabra que prefiera el equipo de diseño tras debatirlo."}, {"id": "d", "texto": "Con el término más técnico, porque es el más preciso de todos."}], "explicacion": "Esto es etiquetado: definir la terminología del sistema. La buena voluntad del equipo no basta. Hay que conocer el pensamiento de los usuarios con un test UX: cómo lo llamarían, cómo lo buscarían y si entienden los términos. Cada gran tienda usa una etiqueta distinta para lo mismo (diapositiva 96), así que copiar no garantiza nada.", "diapositiva": 94}, {"id": "q18", "tipo": "multiple", "enunciado": "¿Cuáles son los tres focos principales de la arquitectura de la información?", "opciones": [{"id": "a", "texto": "Organización", "correcta": true}, {"id": "b", "texto": "Etiquetado", "correcta": true}, {"id": "c", "texto": "Estructura", "correcta": true}, {"id": "d", "texto": "Tipografía"}, {"id": "e", "texto": "Paleta de color"}, {"id": "f", "texto": "Animaciones"}], "explicacion": "Los tres focos son organización (agrupar los contenidos), etiquetado (elegir las palabras) y estructura (definir la navegación y la búsqueda). Tipografía, color y animaciones son decisiones de interfaz (UI), no de arquitectura de la información.", "diapositiva": 84}, {"id": "q19", "tipo": "vf", "grupo": "jerarquica-libre", "enunciado": "En una estructura jerárquica, el usuario puede saltar libremente de una rama a otra sin volver atrás.", "correcta": false, "explicacion": "Es falso. Ese es justo el inconveniente de la jerárquica: para ir a otra rama hay que volver sobre tus pasos o empezar de nuevo y tomar otras decisiones. No se permite la libre navegación.", "diapositiva": 103}, {"id": "q20", "tipo": "vf", "enunciado": "En la navegación de red hay lógica, pero no hay orden: no existe un primero ni un segundo.", "correcta": true, "explicacion": "Es verdadero. Desde el origen se accede a otros bloques sin orden aparente. Las relaciones tienen lógica, pero no hay una secuencia de primero, segundo, tercero.", "diapositiva": 108}, {"id": "q21", "tipo": "unica", "enunciado": "Al trabajar la estructura de una web, ¿qué hacemos?", "opciones": [{"id": "a", "texto": "Definir el modelo de navegación y las herramientas de búsqueda.", "correcta": true}, {"id": "b", "texto": "Definir los títulos, los encabezados y los nombres de las secciones."}, {"id": "c", "texto": "Agrupar la información en categorías de contenidos relacionados."}, {"id": "d", "texto": "Elegir los colores, las tipografías y los iconos de la interfaz."}], "explicacion": "La estructura define el modelo de navegación y las herramientas de búsqueda. Si no resulta natural, previsible y familiar, el usuario la ignora. Elegir títulos y nombres es etiquetado. Agrupar en categorías es organización. Colores y tipografías son interfaz (UI).", "diapositiva": 101}, {"id": "q22", "tipo": "vf", "enunciado": "La estructura lineal es una buena idea para una tienda con miles de productos y muchas opciones.", "correcta": false, "explicacion": "Es falso. La lineal solo es posible cuando la información es poca o sencilla, o cuando el usuario tiene pocas opciones. Con miles de productos, ir solo al siguiente o al anterior sería eterno.", "diapositiva": 107}]};
